-- 用户表
CREATE TABLE sys_user (
    user_id     BIGINT PRIMARY KEY,
    user_name   VARCHAR(30) NOT NULL,
    dept_id     BIGINT
);

-- 用户-角色关联（N:N 中间表）
CREATE TABLE sys_user_role (
    user_id BIGINT NOT NULL,
    role_id BIGINT NOT NULL,
    PRIMARY KEY (user_id, role_id)
);

-- 角色表：data_scope 决定数据权限维度
CREATE TABLE sys_role (
    role_id    BIGINT PRIMARY KEY,
    role_name  VARCHAR(30) NOT NULL,
    role_key   VARCHAR(100) NOT NULL,   -- 前端 v-hasRole 用
    data_scope CHAR(1) DEFAULT '1'      -- 1全部 2自定义 3本部门 4本部门及以下 5仅本人
);

-- 角色-菜单关联
CREATE TABLE sys_role_menu (
    role_id BIGINT NOT NULL,
    menu_id BIGINT NOT NULL,
    PRIMARY KEY (role_id, menu_id)
);

-- 菜单/权限表：perms 是后端校验的权限字符串
CREATE TABLE sys_menu (
    menu_id   BIGINT PRIMARY KEY,
    menu_name VARCHAR(50),
    menu_type CHAR(1),                   -- M目录 C菜单 F按钮
    perms     VARCHAR(100)               -- 如 system:user:list
);

package com.ruoyi.framework.web.service;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import com.ruoyi.common.core.domain.entity.SysMenu;
import com.ruoyi.common.core.domain.entity.SysRole;
import com.ruoyi.system.service.ISysMenuService;
import org.springframework.stereotype.Service;

@Service
public class SysPermissionService {

    private final ISysMenuService menuService;

    public SysPermissionService(ISysMenuService menuService) {
        this.menuService = menuService;
    }

    /** 登录时调用：角色键集合 + 权限字符串集合，写入 LoginUser 缓存 */
    public Set<String> getMenuPermission(SysUser user) {
        Set<String> perms = new HashSet<>();
        // 管理员直接拥有全部权限
        if (user.isAdmin()) {
            perms.add("*:*:*");
            return perms;
        }
        List<SysRole> roles = user.getRoles();
        if (!roles.isEmpty()) {
            // 多角色权限取并集
            List<SysMenu> menus = menuService.selectMenuPermsByRoleId(roles);
            for (SysMenu menu : menus) {
                for (String perm : menu.getPerms().split(",")) {
                    if (!perm.isEmpty()) {
                        perms.addAll(java.util.Arrays.asList(perm.split(":")) == null
                            ? java.util.Collections.emptySet()
                            : java.util.Collections.singleton(perm.trim()));
                    }
                }
            }
        }
        return perms;
    }
}

class SysUser {
    Long userId;
    List<SysRole> roles;
    boolean isAdmin() {
        return userId != null && userId == 1L;
    }
}
